// Phase-2 acceptance (docs/plan/05-migration.md): the tables generated by
// `bun run render` match the v0-final README cell for cell — the regression
// test for the whole data model. Run: `bun run scripts/acceptance-phase2.ts`
//
// Target tables are parsed from `git show v0-final:README.md`; generated
// tables are parsed from the current README's <!-- gen:… --> sections.
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { type MdTable, parseTables } from "../bench/src/render/markdown.ts";

const repoRoot = join(import.meta.dir, "..");

const v0 = await Bun.$`git show v0-final:README.md`.text();
const current = readFileSync(join(repoRoot, "README.md"), "utf8");

const targetTables = parseTables(v0);
const generatedTables = parseTables(current);

// Post-migration semantics: rebenched deployments legitimately drift (the
// first nerf/improvement data points) — their rows are exempt; every row
// still on its legacy-v0 run must reproduce v0 exactly.
const deployments = JSON.parse(
  readFileSync(join(repoRoot, "build", "deployments.json"), "utf8"),
) as Array<{ deployment_id: string; display?: string }>;
const runs = JSON.parse(
  readFileSync(join(repoRoot, "build", "decision.runs.json"), "utf8"),
) as Array<{ deployment: string; source: string }>;
const rebenched = new Set(runs.filter((r) => r.source === "bench").map((r) => r.deployment));
const exemptRows = new Set(
  deployments
    .filter((d) => rebenched.has(d.deployment_id))
    .map((d) => (d.display ?? "").replace(" †", "")),
);
const NAME_ALIASES: Record<string, string> = {
  "Jev (cloud)": "Jev (cloud, jev-1.14.0)", // the cost table's shorter name
};
const isExempt = (rowName: string) => {
  const bare0 = rowName.replace(" †", "").replace(" ‡", "").trim();
  const bare = NAME_ALIASES[bare0] ?? bare0;
  for (const ex of exemptRows) {
    if (
      ex &&
      (bare === ex || bare.startsWith(`${ex} (`) || ex.startsWith(`${bare} (`) || bare.includes(ex))
    ) {
      return true;
    }
  }
  return false;
};

// compare by matching headings; report every missing/extra/differing table
const byHeading = (ts: MdTable[]) => new Map(ts.map((t) => [t.heading, t]));
const target = byHeading(targetTables);
const generated = byHeading(generatedTables);

let failures = 0;
const compare = (t: MdTable, g: MdTable | undefined, label: string) => {
  if (!g) {
    console.error(`FAIL [${label}] no generated table under heading "${t.heading}"`);
    failures++;
    return;
  }
  if (t.header.join("|") !== g.header.join("|")) {
    console.error(`FAIL [${label}] header differs under "${t.heading}"`);
    console.error(`  target:   ${t.header.join("|")}`);
    console.error(`  generated:${g.header.join("|")}`);
    failures++;
    return;
  }
  // name-keyed, order-insensitive: rebenched rows legitimately re-sort, so
  // positions can shift — every non-exempt target row must still exist with
  // identical cells
  const genByName = new Map(g.rows.map((r) => [r[0] ?? "", r]));
  let compared = 0;
  let skipped = 0;
  for (const tr of t.rows) {
    const name = tr[0] ?? "";
    if (isExempt(name)) {
      skipped++;
      continue;
    }
    const gr = genByName.get(name);
    if (!gr) {
      console.error(
        `FAIL [${label}] "${t.heading}": target row "${name}" missing from generated table`,
      );
      failures++;
      continue;
    }
    for (let c = 0; c < Math.max(tr.length, gr.length); c++) {
      if ((tr[c] ?? "") !== (gr[c] ?? "")) {
        console.error(
          `FAIL [${label}] "${t.heading}" "${name}" col ${c + 1}: target "${tr[c] ?? ""}" != generated "${gr[c] ?? ""}"`,
        );
        failures++;
        break;
      }
    }
    compared++;
  }
  console.log(
    `OK   [${label}] "${t.heading}" (${compared} compared, ${skipped} rebenched-skipped)`,
  );
};

// every numeric benchmark table in the v0 README must be reproduced
const benchmarkHeadings = targetTables
  .map((t) => t.heading)
  .filter((h) =>
    ["Mixed-pool spectrum benchmark", "Multilingual", "NER", "rerank", "trial", "cost"].some((k) =>
      h.toLowerCase().includes(k.toLowerCase()),
    ),
  );

if (benchmarkHeadings.length === 0) {
  console.error("FAIL found no benchmark tables in the v0-final README (parser?)");
  process.exit(1);
}

for (const heading of benchmarkHeadings) {
  const t = target.get(heading);
  if (!t) continue;
  compare(t, generated.get(heading), "v0");
}

console.log(`phase-2 acceptance: ${benchmarkHeadings.length} target tables, ${failures} failures`);
if (failures > 0) process.exit(1);
